function normText(v){return (v||'').toString().trim();}
function parseCoord(v){return parseFloat(normText(v).replace(',','.'));}
function inPilotBounds(lat,lng){return lat>=PILOT_BBOX.south&&lat<=PILOT_BBOX.north&&lng>=PILOT_BBOX.west&&lng<=PILOT_BBOX.east;}
