function normalizeKey(v){
  return normText(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,' ').replace(/\s+/g,' ').trim();
}
function classifyBrand(raw){
  const x=normalizeKey(raw);
  if(x.includes('MOEVE')||x.includes('CEPSA')) return 'MOEVE';
  if(x.includes('DISA')) return 'DISA';
  if(x.includes('REPSOL')) return 'REPSOL';
  if(x.includes('SHELL')) return 'SHELL';
  if(x==='BP'||x.startsWith('BP ')||x.includes(' BP ')) return 'BP';
  if(x.includes('PCAN')) return 'PCAN';
  if(x.includes('TGAS')||x.includes('T GAS')||x.includes('TREBOL')) return 'TGAS';
  if(x.includes('PLENERGY')||x.includes('PLENOIL')) return 'PLENERGY';
  if(x.includes('BALLENOIL')) return 'BALLENOIL';
  if(x.includes('PETROPRIX')) return 'PETROPRIX';
  if(x.includes('GALP')) return 'GALP';
  if(x==='AVIA'||x.startsWith('AVIA ')||x.includes(' AVIA ')) return 'AVIA';
  if(x.includes('Q8')) return 'Q8';
  if(x.includes('ALCAMPO')||x.includes('AUCHAN')) return 'ALCAMPO';
  if(x.includes('CARREFOUR')) return 'CARREFOUR';
  if(x.includes('EASYGAS')||x.includes('EASY GAS')) return 'EASYGAS';
  if(x.includes('FAMILY ENERGY')) return 'FAMILYENERGY';
  if(x.includes('PETRONOR')||x.includes('CAMPSA')) return 'REPSOL';
  if(x.includes('H2EXAGON')||x.includes('H2 EXAGON')||x.includes('H2EXA')||x.includes('1H2GO')) return 'H2EXAGON';
  if(x.includes('OCEANO')) return 'OCEANO';
  if(x.includes('PETROPRIX')) return 'PETROPRIX';
  if(x.includes('PETROCAN')) return 'PETROCAN';
  if(x.includes('CANARY OIL')) return 'CANARYOIL';
  if(x.includes('GMOIL')) return 'GMOIL';
  if(x.includes('COMBUSTIBLES CANARIOS')) return 'COMBCAN';
  return 'OTHER';
}

