function brandOverrideKey(id){return `brandOverride__${id}`;}
function brandOverride(id){return state[brandOverrideKey(id)]||null;}

function resolveBrandRecord(station){
  const override=brandOverride(station.id);
  if(override?.brand){
    return {brand:override.brand, confidence:'Equipo', source:'Corrección manual del equipo', sourceUrl:'', reason:override.note||'Operador corregido manualmente.'};
  }
  const direct=classifyBrand(station.rawBrand||station.name||'');
  if(direct!=='OTHER'){
    return {brand:direct, confidence:'Alta', source:'Rótulo público', sourceUrl:'', reason:'Marca reconocida directamente en el rótulo/nombre público.'};
  }
  const hay=normalizeKey([station.rawBrand,station.name,station.address,station.municipality].filter(Boolean).join(' | '));
  const muni=normalizeKey(station.municipality);
  for(const rule of BRAND_RESOLUTION_RULES){
    const muniOk=!rule.municipality||muni.includes(normalizeKey(rule.municipality));
    const anyOk=(rule.any||[]).some(t=>hay.includes(normalizeKey(t)));
    if(muniOk&&anyOk){
      return {brand:rule.brand, confidence:rule.confidence, source:rule.source, sourceUrl:rule.sourceUrl||'', reason:'Coincidencia con estación/dirección de red verificada.'};
    }
  }
  return {brand:'OTHER', confidence:'Baja', source:'Sin resolver', sourceUrl:'', reason:'No hay evidencia suficiente para asignar una marca con confianza.'};
}
function applyBrandResolution(station){
  const r=resolveBrandRecord(station);
  station.brand=r.brand;
  station.brandConfidence=r.confidence;
  station.brandSource=r.source;
  station.brandSourceUrl=r.sourceUrl;
  station.brandReason=r.reason;
  return station;
}
function refreshBrandResolution(){
  stations.forEach(applyBrandResolution);
}
