function distanceKm(a,b){const R=6371,r=Math.PI/180,dLat=(b.lat-a.lat)*r,dLon=(b.lng-a.lng)*r,x=Math.sin(dLat/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dLon/2)**2;return 2*R*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}


function pointSegmentDistanceKm(p,a,b){
  const lat0=p.lat*Math.PI/180, kx=111.32*Math.cos(lat0), ky=110.574;
  const px=p.lng*kx, py=p.lat*ky, ax=a[1]*kx, ay=a[0]*ky, bx=b[1]*kx, by=b[0]*ky;
  const dx=bx-ax,dy=by-ay,den=dx*dx+dy*dy; let t=den?((px-ax)*dx+(py-ay)*dy)/den:0;t=Math.max(0,Math.min(1,t));
  return Math.hypot(px-(ax+t*dx),py-(ay+t*dy));
}
function distanceToPilotRoute(s){let best=Infinity;for(let i=1;i<pilotRouteGeometry.length;i++){const d=pointSegmentDistanceKm(s,pilotRouteGeometry[i-1],pilotRouteGeometry[i]);if(d<best)best=d;if(best<0.15)break;}return best;}
function scopeMatches(s){
  if(currentScope==='alicante') return s.provinceCode==='03';
  const d=Number.isFinite(s.routeDistanceKm)?s.routeDistanceKm:distanceToPilotRoute(s);
  if(currentScope==='corridor') return d<=8;
  return s.provinceCode==='03'||d<=8;
}
function visibleStations(){return stations.filter(scopeMatches);}
function scopeLabel(){return currentScope==='alicante'?'Alicante provincia':currentScope==='corridor'?'Ruta Madrid → Alicante · ≤8 km':'Piloto completo · ruta + Alicante';}
async function requestRoadRoute(points,optimizeWaypoints=false){
  const payload={points:points.map(p=>({lat:Number(p.lat),lng:Number(p.lng)})),optimizeWaypoints};
  const r=await fetch(ROUTE_API_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
  if(!r.ok) throw new Error(`Route API ${r.status}`);
  const data=await r.json();
  if(!Array.isArray(data.coordinates)||data.coordinates.length<2) throw new Error('Ruta Azure vacía');
  return data;
}
async function loadPilotRoute(){
  try{
    const data=await requestRoadRoute([{lat:40.4168,lng:-3.7038},{lat:38.3452,lng:-0.4907}],false);
    pilotRouteGeometry=data.coordinates;pilotRouteDistanceKm=data.distanceKm||null;currentRouteProvider=data.provider||'Azure Maps';
  }catch(e){
    console.warn('Azure route unavailable',e);
    // Solo para desarrollo local: OSRM mantiene una geometría de carretera real. En Azure la API corporativa es la fuente principal.
    try{const r=await fetch(DEV_OSRM_ROUTE_URL);if(!r.ok)throw new Error('OSRM '+r.status);const d=await r.json(),route=d.routes?.[0];if(!route?.geometry?.coordinates?.length)throw new Error('Ruta vacía');pilotRouteDistanceKm=route.distance/1000;pilotRouteGeometry=route.geometry.coordinates.filter((_,i)=>i%3===0||i===route.geometry.coordinates.length-1).map(c=>[c[1],c[0]]);currentRouteProvider='OSRM · desarrollo local';}
    catch(e2){console.warn('Route fallback',e2);pilotRouteGeometry=FALLBACK_PILOT_ROUTE.slice();pilotRouteDistanceKm=null;currentRouteProvider='Fallback';}
  }
}
function drawPilotRoute(){if(!pilotRouteLayer)return;pilotRouteLayer.clearLayers();L.polyline(pilotRouteGeometry,{color:'#004556',weight:4,opacity:.8}).addTo(pilotRouteLayer);}
