window.setPilotScope=scope=>{currentScope=scope;localStorage.setItem('moevePilotScope',scope);updateScopeUI();populateMoeveDropdown();renderMarkers();fitPilotScope();renderRoute();};
function fitPilotScope(){const vis=visibleStations();if(!vis.length)return;if(currentScope==='corridor'){map.fitBounds(L.latLngBounds(pilotRouteGeometry),{padding:[24,24]});return;}const b=L.latLngBounds(vis.map(s=>[s.lat,s.lng]));if(b.isValid())map.fitBounds(b,{padding:[20,20],maxZoom:11});}
function overlapScore(station){
  let score=0, reasons=[];
  const rv=getReviews(station.id), prof=profile();
  if(station.hours && /24/.test(station.hours)){score+=1;reasons.push('Horario amplio / 24h');}
  const moveText=((state.__competitiveMoves||[]).filter(m=>m.competitorId===station.id||m.moeveId===current?.id).map(m=>`${m.title} ${m.detail||''}`).join(' ')+' '+(rv.frictions||'')+' '+(rv.positives||'')).toLowerCase();
  if(/opt|pago|qr/.test(moveText)){score+=1;reasons.push('Señales de oferta/pago comparables');}
  if(/caf[eé]|tienda|baño|lavado/.test(moveText)){score+=1;reasons.push('Señales de conveniencia / servicios comparables');}
  if(prof.text){score+=1;reasons.push('Existe perfil objetivo definido para contrastar');}
  return {score,reasons};
}
function journeyExplanation(station){
  const rel=getCompRelation(station), d=distanceKm(current,station), ov=overlapScore(station), dataUsed=[];
  dataUsed.push(`Distancia geográfica: ${d.toFixed(1)} km`);
  dataUsed.push(`Clasificación actual: ${rel.label}${rel.source==='team'?' (definida por el equipo)':rel.source==='proxy'?' (proxy automática)':''}`);
  if(station.hours) dataUsed.push(`Horario público: ${station.hours}`);
  if(ov.reasons.length) dataUsed.push(...ov.reasons);
  const why=[];
  if(rel.source==='team') why.push('El equipo ha marcado manualmente esta estación como relevante/potencial/contexto para el mismo journey.');
  else if(d<=3) why.push('A falta de una clasificación manual, la herramienta usa proximidad como proxy inicial y la marca como Potencial.');
  else why.push('No hay evidencia suficiente para tratarla como competidor directo; se mantiene como contexto.');
  if(ov.score) why.push(`Se han detectado ${ov.score} señal(es) adicionales de posible solape de journey.`);
  const confidence = rel.source==='team' ? 'Media/Alta' : ov.score>=2 ? 'Media' : 'Baja';
  return {why: why.join(' '), dataUsed, confidence, distance:d, relation:rel};
}
function relevantPotentialCount(radius=5){
  const list=nearby(radius).filter(x=>x.brand!=='MOEVE'&&x._p.level!=='green');
  return {count:list.length,list};
}
function explainableBadgeHTML(station){
  const p=station._p||pressureForStation(station);
  return `<button class="badge ${p.level==='red'?'primary':p.level==='yellow'?'secondary':'context'}" onclick="event.stopPropagation();explainStationReason('${station.id}')">${p.label}</button>`;
}
window.explainStationReason=id=>{
  const s=stations.find(x=>x.id===id); if(!s||!current)return;
  const exp=journeyExplanation(s);
  showModal(`<div class="eyebrow">EXPLICACIÓN</div><h2>${esc(s.name)}</h2><div class="formula"><b>Clasificación mostrada</b><br>${esc(exp.relation.label)} · ${esc(exp.why)}</div><div class="formula"><b>Datos utilizados</b><br><ul>${exp.dataUsed.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="formula"><b>Confianza</b><br>${esc(exp.confidence)}</div><button class="secondary-btn" onclick="closeModal()">Cerrar</button>`);
};
window.explainRelevantPotential=()=>{
  const res=relevantPotentialCount(5);
  showModal(`<div class="eyebrow">EXPLICACIÓN</div><h2>Alternativas potenciales para el mismo journey</h2><div class="formula"><b>Qué significa el número</b><br>${res.count} = nº de estaciones no Moeve en 5 km con etiqueta <b>Relevante</b> o <b>Potencial</b>.</div><div class="formula"><b>Cómo se calcula</b><br><ol><li>Se toma la Moeve seleccionada como estación base.</li><li>Se buscan EESS del entorno en un radio de 5 km.</li><li>Se excluyen las Moeve.</li><li>Se cuentan solo las estaciones etiquetadas como Primary/Relevante o Secondary/Potencial.</li></ol></div><div class="formula"><b>Importante</b><br>La etiqueta puede venir de clasificación manual del equipo o de un proxy automático basado en proximidad hasta que el equipo la revise.</div>${res.list.length?`<div class="formula"><b>Estaciones incluidas ahora mismo</b><br><ul>${res.list.map(s=>`<li>${esc(s.name)} · ${esc(s._p.label)} · ${s._d.toFixed(1)} km</li>`).join('')}</ul></div>`:''}`);
};
window.explainJourneyReason=id=>{
  const s=stations.find(x=>x.id===id); if(!s)return; const exp=journeyExplanation(s);
  showModal(`<div class="eyebrow">MISMO JOURNEY</div><h2>${esc(s.name)}</h2><div class="formula"><b>Por qué aparece aquí</b><br>${esc(exp.why)}</div><div class="formula"><b>Datos utilizados</b><br><ul>${exp.dataUsed.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="formula"><b>Nivel de confianza</b><br>${esc(exp.confidence)}</div>`);
};

