function logoFallback(el,brand){
  const parent=el?.parentElement;if(!parent)return;
  const embedded=LOGO_ASSETS[brand];
  if(embedded){parent.innerHTML=`<img src="${embedded}" alt="" aria-hidden="true">`;return;}
  parent.innerHTML=compactSvgMark(brand)||neutralBrandMark();
}
window.logoFallback=logoFallback;
