function responseKey(qid){return `visit__${current.id}__${qid}`;}
function renderVisit(){const pr=customerPriorityItems()[0]||['Customer journey','Valida la experiencia completa.'];document.getElementById('visit').innerHTML=`<div class="card tint-blue"><div class="eyebrow">VALIDACIÓN DE CAMPO · CUSTOMER JOURNEY</div><div class="big-insight">Hipótesis prioritaria: ${esc(pr[0])}</div><div class="muted">${esc(pr[1])}</div></div>${FIELD_SECTIONS.map(sec=>`<div class="question-section"><div class="eyebrow">${sec.title}</div>${sec.questions.map(renderQuestion).join('')}</div>`).join('')}<button class="primary-btn" onclick="saveVisit()">Guardar visita</button>`;setTimeout(loadPhotoPreviews,50);}
function renderQuestion(q){const v=state[responseKey(q.id)]||{};let answer='';if(q.type==='yesno')answer=`<div class="choices">${['Sí','No','No sé'].map(x=>`<button class="choice ${v.answer===x?'selected':''}" onclick="setChoice('${q.id}','${x}',this)">${x}</button>`).join('')}</div>`;else answer=`<div class="field"><textarea rows="3" placeholder="Escribe la observación…" oninput="setText('${q.id}',this.value)">${esc(v.text||'')}</textarea></div>`;const photos=q.type==='textphoto'?`<div class="photo-box"><input type="file" accept="image/*" capture="environment" multiple onchange="savePhotos('${q.id}',this.files)"><div class="mini-note">Fotos ligadas a esta pregunta y estación.</div><div class="photo-preview" id="photos_${q.id}"></div></div>`:'';return `<div class="question-card"><div class="q-title">${q.q}</div><div class="q-help">${q.help}</div>${answer}${photos}<button class="secondary-btn" onclick="createTodoFromQuestion('${q.id}','${q.q.replaceAll("'",'')}')">+ Crear TO DO desde esta respuesta</button></div>`;}
window.setChoice=(qid,answer,btn)=>{const k=responseKey(qid),prev=(state[k]||{}).answer;state[k]=state[k]||{};state[k].answer=answer;state[k].updatedAt=new Date().toISOString();persist();btn.parentElement.querySelectorAll('.choice').forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');if(prev&&prev!==answer)addAlert(current.id,`Cambio en ${qid}`,`La respuesta cambió de “${prev}” a “${answer}”.`,'medium','FIELD_CHANGE');renderCopilot();renderCustomer();};
