function todoKey(){return '__todos';}
window.createTodoFromQuestion=(qid,question)=>{const action=prompt('¿Qué hay que hacer?');if(!action)return;const owner=prompt('¿Quién es responsable?')||'Sin asignar',due=prompt('¿Fecha objetivo? (AAAA-MM-DD, opcional)')||'';state[todoKey()]=state[todoKey()]||[];state[todoKey()].push({id:'td-'+Date.now(),stationId:current.id,question,qid,action,owner,due,status:'Abierto',createdAt:new Date().toISOString()});addAlert(current.id,'Nuevo TO DO',action,'medium','TODO');persist();renderTodos();renderAlerts();};
function renderTodos(){const arr=todosFor(current.id);document.getElementById('todo').innerHTML=`<div class="card"><div class="eyebrow">ACCIONES</div><h3>TO DO de esta estación</h3>${arr.length?arr.map(t=>`<div class="todo-item"><div class="row-top"><div class="row-title">${esc(t.action)}</div><span class="badge">${esc(t.status)}</span></div><div class="row-sub">Origen: ${esc(t.question)}</div><div class="row-sub">Responsable: ${esc(t.owner)}${t.due?' · '+esc(t.due):''}</div>${t.status!=='Cerrado'?`<div class="todo-actions"><button class="tiny-btn" onclick="closeTodo('${t.id}')">Marcar completado</button></div>`:''}</div>`).join(''):`<div class="empty">Todavía no hay acciones abiertas.</div>`}</div>`;}
