function alertsKey(){return '__alerts';}
function addAlert(stationId,title,detail,priority='low',type='CHANGE'){state[alertsKey()]=state[alertsKey()]||[];state[alertsKey()].unshift({id:'al-'+Date.now()+'-'+Math.random().toString(36).slice(2,5),stationId,title,detail,priority,type,createdAt:new Date().toISOString(),read:false});state[alertsKey()]=state[alertsKey()].slice(0,700);persist();}
