function renderRoute(){
  const rs=routeStations(),available=visibleStations().filter(s=>s.brand==='MOEVE'&&!routeIds().includes(s.id)).sort((a,b)=>a.name.localeCompare(b.name)),intel=routeIntelligence();
  const routeSignals=[];
  if(intel.primary||intel.secondary) routeSignals.push(`<div class="route-signal competition compact-signal"><b>Competencia</b><span>${intel.primary} relevante(s) · ${intel.secondary} potencial(es) clasificados por journey.</span></div>`);
  if(intel.frictionStops) routeSignals.push(`<div class="route-signal customer compact-signal"><b>Customer voice</b><span>${intel.frictionStops} parada(s) con fricciones registradas.</span></div>`);
  if(intel.moves) routeSignals.push(`<div class="route-signal competition compact-signal"><b>Cambios competitivos</b><span>${intel.moves} movimiento(s) registrado(s) en la ruta.</span></div>`);
  const routeMeta=state.__lastRouteSummary?`<div class="route-meta"><b>Ruta por carretera:</b> ${esc(state.__lastRouteSummary.provider||'Azure Maps')}${state.__lastRouteSummary.distanceKm?' · '+Math.round(state.__lastRouteSummary.distanceKm)+' km':''}${state.__lastRouteSummary.durationMinutes?' · '+Math.round(state.__lastRouteSummary.durationMinutes)+' min':''}</div>`:'';document.getElementById('route').innerHTML=`${routeMeta}${routeSignals.length?`<div class="compact-signal-list">${routeSignals.join('')}</div>`:''}<div class="card"><h3>Ruta actual</h3>${rs.map((s,i)=>`<div class="route-item ${current.id===s.id?'current':''}"><div class="route-row"><div class="route-index">${i+1}</div><div class="comp-main"><div class="row-title">${esc(s.name)}</div><div class="row-sub">${esc(s.municipality||s.address)}</div><div class="route-concession"><label>Nº de concesión</label><input value="${esc(getConcession(s.id))}" placeholder="Introduce nº de concesión" onchange="saveRouteConcession('${s.id}',this.value)"></div><div class="route-actions"><button class="tiny-btn" onclick="setRouteStop(${i})">Mapa</button><button class="tiny-btn route-brief-btn" onclick="openCopilotForStop(${i})">Briefing</button>${i>0?`<button class="tiny-btn" onclick="moveRoute(${i},-1)">↑</button>`:''}${i<rs.length-1?`<button class="tiny-btn" onclick="moveRoute(${i},1)">↓</button>`:''}${rs.length>1?`<button class="tiny-btn" onclick="removeRoute(${i})">Quitar</button>`:''}</div></div></div></div>`).join('')}</div>${available.length?`<div class="card"><h3>Añadir parada Moeve</h3><div class="route-add"><select id="routeAddSelect">${available.map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.municipality)}</option>`).join('')}</select><button class="tiny-btn" onclick="addRoute()">Añadir</button></div></div>`:''}`;
}
window.addRoute=()=>{const id=document.getElementById('routeAddSelect')?.value;if(id&&!routeIds().includes(id)){state.__route.push(id);persist();renderRoute();renderMarkers();renderRouteToolbar();}};
window.removeRoute=i=>{if(routeIds().length<=1)return;const removing=routeIds()[i];state.__route.splice(i,1);persist();if(current.id===removing)selectStation(routeIds()[Math.min(i,routeIds().length-1)],true);else{renderRoute();renderMarkers();renderRouteToolbar();}};
