window.explainPressure=()=>showModal(`<div class="eyebrow">EXPLAIN THIS</div><h2>Halos competitivos</h2><div class="formula"><b>Rojo</b><br>Competidor marcado como Primary: alternativa relevante para el mismo journey.</div><div class="formula"><b>Amarillo</b><br>Secondary o candidato próximo pendiente de validar.</div><div class="formula"><b>Verde</b><br>Context station / baja presión. Sigue visible porque necesitamos conocer todas las EESS del entorno.</div><div class="formula"><b>Principio</b><br>Una estación no es competidor solo porque esté cerca. El equipo puede corregir la relevancia desde la ficha de cada EESS.</div>`);
