let dbPromise=null;function openDB(){if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('moeveFieldV32',1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('photos')){const s=db.createObjectStore('photos',{keyPath:'id'});s.createIndex('stationId','stationId');s.createIndex('stationQuestion','stationQuestion');}};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});return dbPromise;}
window.savePhotos=async(qid,files)=>{const db=await openDB(),tx=db.transaction('photos','readwrite'),store=tx.objectStore('photos');for(const f of [...files]){const id='ph-'+Date.now()+'-'+Math.random().toString(36).slice(2,8);store.put({id,stationId:current.id,qid,stationQuestion:`${current.id}__${qid}`,filename:f.name,type:f.type,size:f.size,createdAt:new Date().toISOString(),blob:f});}await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});addAlert(current.id,'Nueva evidencia fotográfica',`${files.length} foto(s) añadidas a ${qid}.`,'low','PHOTO');renderPhotoPreview(qid);};
async function getPhotos(stationId,qid){const db=await openDB();return new Promise((res,rej)=>{const tx=db.transaction('photos','readonly'),idx=tx.objectStore('photos').index('stationQuestion'),r=idx.getAll(`${stationId}__${qid}`);r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error);});}
async function getAllPhotos(){const db=await openDB();return new Promise((res,rej)=>{const tx=db.transaction('photos','readonly'),r=tx.objectStore('photos').getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error);});}
async function getAllPhotosMeta(){return (await getAllPhotos()).map(({blob,...m})=>m);}
async function renderPhotoPreview(qid){const box=document.getElementById(`photos_${qid}`);if(!box)return;const photos=await getPhotos(current.id,qid);box.innerHTML=photos.map(p=>`<div class="photo-thumb"><img src="${URL.createObjectURL(p.blob)}"><span>${esc(p.filename)}</span></div>`).join('');}
function loadPhotoPreviews(){FIELD_SECTIONS.flatMap(x=>x.questions).filter(q=>q.type==='textphoto').forEach(q=>renderPhotoPreview(q.id));}

function safePathPart(v){return normText(v).replace(/[\\/:*?"<>|]+/g,'_').replace(/\s+/g,'_').replace(/^_+|_+$/g,'')||'SIN_DATO';}
function questionLabel(qid){for(const sec of FIELD_SECTIONS){const q=sec.questions.find(x=>x.id===qid);if(q)return q.q;}return qid;}
function photoRelativePath(p){
  const station=stations.find(s=>s.id===p.stationId),zone=zoneForStation(station||p.stationId),date=visitDateForStation(p.stationId),con=getConcession(p.stationId);
  const folder=con?`CONCESION_${safePathPart(con)}`:`SIN_CONCESION_${safePathPart(p.stationId)}`;
  const ext=(p.filename&&p.filename.includes('.'))?'.'+p.filename.split('.').pop():'';
  const stamp=(p.createdAt||'').replace(/[-:TZ.]/g,'').slice(0,14)||Date.now();
  const base=safePathPart((p.filename||'foto').replace(/\.[^.]+$/,''));
  return `Fotos/${safePathPart(zone)}/${date}/${folder}/${safePathPart(p.qid)}_${stamp}_${base}${ext}`;
}
function visitSessionRows(){
  const sessions=(state.__visitSessions||[]).map(v=>({...v,Concession_No:getConcession(v.stationId)||v.concessionNo||''}));
  const existing=new Set(sessions.map(x=>x.stationId+'|'+(x.savedAt||'')));
  Object.entries(state).filter(([k])=>k.startsWith('lastVisit__')).forEach(([k,iso])=>{const sid=k.replace('lastVisit__',''),key=sid+'|'+iso;if(existing.has(key))return;const s=stations.find(x=>x.id===sid);sessions.push({id:'legacy',zone:zoneForStation(s||sid),visitDate:(iso||'').slice(0,10),Concession_No:getConcession(sid),stationId:sid,stationName:s?.name||'',savedAt:iso});});
  return sessions;
}
function buildWorkbook(photoRecords=[]){
  const stationRows=stations.map(s=>({Concession_No:getConcession(s.id),Station_ID:s.id,Name:s.name,Public_Rotulo:s.rawBrand||'',Resolved_Brand:s.brand,Brand_Label:brandLabel(s),Brand_Confidence:s.brandConfidence||'',Brand_Source:s.brandSource||'',Brand_Reason:s.brandReason||'',Address:s.address,Municipality:s.municipality,Latitude:s.lat,Longitude:s.lng,Hours:s.hours,Province:s.province||'',Route_Distance_km:Number.isFinite(s.routeDistanceKm)?Math.round(s.routeDistanceKm*10)/10:'',In_Pilot_Scope:scopeMatches(s)?'Sí':'No',Source:s.source}));
  const visits=[];Object.entries(state).filter(([k])=>k.startsWith('visit__')).forEach(([k,v])=>{const [,sid,qid]=k.split('__');visits.push({Zone:zoneForStation(sid),Visit_Date:visitDateForStation(sid),Concession_No:getConcession(sid),Station_ID:sid,Question_ID:qid,Question:questionLabel(qid),Answer:v.answer||'',Observation:v.text||'',Updated_At:v.updatedAt||''});});
  const reviews=[];Object.entries(state).filter(([k])=>k.startsWith('reviews__')).forEach(([k,v])=>reviews.push((sid=>({Zone:zoneForStation(sid),Concession_No:getConcession(sid),Station_ID:sid,Positives:v.positives||'',Frictions:v.frictions||'',Recent_Signal:v.recent||'',Source_URL:v.sourceUrl||'',Confidence:v.confidence||'',Updated_At:v.updatedAt||''}))(k.replace('reviews__',''))));
  const profiles=[];Object.entries(state).filter(([k])=>k.startsWith('profile__')).forEach(([k,v])=>profiles.push((sid=>({Zone:zoneForStation(sid),Concession_No:getConcession(sid),Station_ID:sid,Profile:v.text||'',Confidence:v.confidence||''}))(k.replace('profile__',''))));
  const relations=[];Object.entries(state).filter(([k])=>k.startsWith('comp__')).forEach(([k,v])=>{const [,moeveId,otherId]=k.split('__');relations.push({Moeve_Concession_No:getConcession(moeveId),Moeve_Station_ID:moeveId,Other_Station_ID:otherId,Journey_Relation:v.relation||'',Updated_At:v.updatedAt||''});});
  const routeRows=routeIds().map((id,i)=>({Order:i+1,Zone:zoneForStation(id),Concession_No:getConcession(id),Station_ID:id,Station_Name:stations.find(s=>s.id===id)?.name||''}));
  const concessionRows=stations.filter(s=>s.brand==='MOEVE'&&getConcession(s.id)).map(s=>({Zone:zoneForStation(s),Concession_No:getConcession(s.id),Station_ID:s.id,Station_Name:s.name,Municipality:s.municipality,In_Current_Route:routeIds().includes(s.id)?'Sí':'No'}));
  const brandRows=stations.map(s=>{const ov=brandOverride(s.id);return {Station_ID:s.id,Name:s.name,Public_Rotulo:s.rawBrand||'',Resolved_Brand:s.brand,Brand_Label:brandLabel(s),Confidence:s.brandConfidence||'',Resolution_Source:s.brandSource||'',Resolution_Reason:s.brandReason||'',Official_Visual_Source:OFFICIAL_BRAND_ASSETS[s.brand]?.source||'',Manual_Override:ov?.brand||'',Manual_Note:ov?.note||'',Address:s.address,Municipality:s.municipality};});
  const photoRows=photoRecords.map(({blob,...p})=>({Zone:zoneForStation(p.stationId),Visit_Date:visitDateForStation(p.stationId),Concession_No:getConcession(p.stationId),Station_ID:p.stationId,Question_ID:p.qid,Question:questionLabel(p.qid),Original_Filename:p.filename||'',Relative_Path:photoRelativePath(p),Mime_Type:p.type||'',Size_Bytes:p.size||'',Created_At:p.createdAt||''}));
  const wb=XLSX.utils.book_new();const add=(name,rows)=>XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows.length?rows:[{Info:'Sin registros'}]),name);
  const moves=(state.__competitiveMoves||[]).map(x=>({...x,Moeve_Concession_No:getConcession(x.moeveId)}));
  const todos=(state.__todos||[]).map(x=>({...x,Zone:zoneForStation(x.stationId),Concession_No:getConcession(x.stationId)}));
  const alerts=(state.__alerts||[]).map(x=>({...x,Zone:zoneForStation(x.stationId),Concession_No:getConcession(x.stationId)}));
  const sessions=visitSessionRows();
  add('Stations',stationRows);add('Brand_Resolution',brandRows);add('Concessions',concessionRows);add('Route',routeRows);add('Visit_Sessions',sessions);add('Journey_Relations',relations);add('Competitive_Moves',moves);add('Field_Observations',visits);add('Customer_Voice',reviews);add('Customer_Profiles',profiles);add('TODOs',todos);add('Alerts',alerts);add('Photos_Index',photoRows);
  return wb;
}
function downloadBlob(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}

function buildStationWorkbook(stationId,photoRecords=[]){
  const s=stations.find(x=>x.id===stationId),con=getConcession(stationId),visitDate=visitDateForStation(stationId),wb=XLSX.utils.book_new();
  const add=(name,rows)=>XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows.length?rows:[{Info:'Sin registros'}]),name);
  add('Station',[{Zone:zoneForStation(s||stationId),Visit_Date:visitDate,Concession_No:con,Station_ID:stationId,Station_Name:s?.name||'',Address:s?.address||'',Municipality:s?.municipality||'',Latitude:s?.lat||'',Longitude:s?.lng||'',Resolved_Brand:s?.brand||'',Brand_Source:s?.brandSource||''}]);
  const obs=[];Object.entries(state).filter(([k])=>k.startsWith(`visit__${stationId}__`)).forEach(([k,v])=>{const qid=k.split('__')[2];obs.push({Question_ID:qid,Question:questionLabel(qid),Answer:v.answer||'',Observation:v.text||'',Updated_At:v.updatedAt||''});});add('Field_Observations',obs);
  const sess=(state.__visitSessions||[]).filter(v=>v.stationId===stationId);add('Visit_Sessions',sess);
  const rv=getReviews(stationId);add('Customer_Voice',(rv.positives||rv.frictions||rv.recent)?[{Positives:rv.positives||'',Frictions:rv.frictions||'',Recent_Signal:rv.recent||'',Source_URL:rv.sourceUrl||'',Confidence:rv.confidence||'',Updated_At:rv.updatedAt||''}]:[]);
  add('TODOs',(state.__todos||[]).filter(x=>x.stationId===stationId));add('Alerts',(state.__alerts||[]).filter(x=>x.stationId===stationId));
  const pp=photoRecords.filter(p=>p.stationId===stationId).map(({blob,...p})=>({Question_ID:p.qid,Question:questionLabel(p.qid),Filename:p.filename||'',Mime_Type:p.type||'',Size_Bytes:p.size||'',Created_At:p.createdAt||''}));add('Photos_Index',pp);
  return wb;
}
async function prepareStationEmailPayload(stationId){
  if(typeof XLSX==='undefined')throw new Error('Módulo Excel no disponible');
  const s=stations.find(x=>x.id===stationId);if(!s)throw new Error('Estación no encontrada');
  const concession=getConcession(stationId);if(!concession)throw new Error('Falta nº de concesión');
  const session=latestVisitSession(stationId);if(!session)throw new Error('Guarda la visita antes de enviarla');
  const allPhotos=await getAllPhotos(),photos=allPhotos.filter(p=>p.stationId===stationId),wb=buildStationWorkbook(stationId,photos),xlsx=XLSX.write(wb,{bookType:'xlsx',type:'array'}),date=(session.visitDate||session.savedAt?.slice(0,10)||new Date().toISOString().slice(0,10));
  const attachments=[{name:`${safePathPart(s.name)}_${safePathPart(concession)}_${date}.xlsx`,contentType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',contentBytes:arrayBufferToBase64(xlsx)}];
  for(const p of photos){attachments.push({name:p.filename||`foto_${p.qid}.jpg`,contentType:p.type||'image/jpeg',contentBytes:await blobToBase64(p.blob),questionId:p.qid});}
  return {stationId,stationName:s.name,concessionNo:concession,visitDate:date,to:'fuelmanagement@moeveglobal.com',subject:`${s.name} - ${concession} - ${date} - VISITA`,attachments};
}
window.sendCurrentVisitEmail=async()=>{
  try{
    updateSaveStatus('Preparando envío…');const payload=await prepareStationEmailPayload(current.id);
    const r=await fetch('/api/send-visit-email',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
    if(!r.ok){const t=await r.text();throw new Error(t||`HTTP ${r.status}`);}const out=await r.json().catch(()=>({}));
    state.__emailSends.unshift({stationId:current.id,concessionNo:payload.concessionNo,visitDate:payload.visitDate,subject:payload.subject,to:payload.to,sentAt:new Date().toISOString(),status:'Enviado'});persist();
    showModal(`<div class="eyebrow">VISITA ENVIADA</div><h2>${esc(current.name)}</h2><div class="card tint-blue"><b>${esc(payload.subject)}</b><div class="muted" style="margin-top:8px">Enviado a ${esc(payload.to)} con Excel y ${payload.attachments.length-1} fotografía(s).</div></div><button class="primary-btn" onclick="closeModal()">Cerrar</button>`);
  }catch(e){console.error(e);updateSaveStatus();showModal(`<div class="eyebrow">ENVÍO PENDIENTE</div><h2>No se ha podido enviar todavía</h2><div class="card tint-yellow"><div class="muted">${esc(e.message||String(e))}</div></div><div class="card"><b>Los datos siguen guardados en este dispositivo.</b><div class="muted" style="margin-top:6px">El envío automático funciona cuando la app está publicada en Azure y el backend corporativo de Microsoft Graph está configurado.</div></div><button class="primary-btn" onclick="closeModal()">Cerrar</button>`);}
};
async function exportExcel(){
  if(typeof XLSX==='undefined'){alert('No se ha podido cargar el módulo Excel. Comprueba la conexión a internet.');return;}
  const photos=await getAllPhotos(),wb=buildWorkbook(photos),date=new Date().toISOString().slice(0,10);
  XLSX.writeFile(wb,`Moeve_Field_Alicante_${date}.xlsx`);
}
async function exportVisitPackage(){
  if(typeof XLSX==='undefined'||typeof JSZip==='undefined'){alert('No se han podido cargar los módulos de exportación. Comprueba la conexión a internet.');return;}
  const photos=await getAllPhotos();
  const missing=[...new Set(photos.filter(p=>!getConcession(p.stationId)).map(p=>stations.find(s=>s.id===p.stationId)?.name||p.stationId))];
  if(missing.length){showModal(`<div class="eyebrow">FALTA Nº DE CONCESIÓN</div><h2>No exporto las fotos todavía</h2><div class="card tint-yellow"><div class="muted">Para mantener la estructura acordada, introduce el nº de concesión en Ruta para estas estaciones:</div><ul>${missing.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><button class="primary-btn" onclick="closeModal();activateTab('route')">Ir a Ruta</button>`);return;}
  const date=new Date().toISOString().slice(0,10),root=`Moeve_Field_Alicante_${date}`,zip=new JSZip(),wb=buildWorkbook(photos),xlsx=XLSX.write(wb,{bookType:'xlsx',type:'array'});
  zip.file(`${root}.xlsx`,xlsx);
  photos.forEach(p=>zip.file(photoRelativePath(p),p.blob));
  zip.file('LEEME.txt',`Paquete Moeve Field Intelligence\\nZona piloto: Madrid → Alicante / Alicante\\nExportado: ${new Date().toLocaleString('es-ES')}\\n\\nFotos organizadas por Zona / Fecha de visita / Nº de concesión.\\nEl Excel incluye Photos_Index con la ruta relativa de cada imagen.`);
  const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE',compressionOptions:{level:6}});
  downloadBlob(blob,`${root}.zip`);
  closeModal();
}
window.openExportMenu=()=>{
  if(isMobileFieldDevice()){
    showModal(`<div class="eyebrow">FINALIZAR VISITA</div><h2>${esc(current?.name||'Estación')}</h2><div class="card tint-blue"><h3>Enviar visita por email</h3><div class="muted">Envía <b>solo esta estación</b> a fuelmanagement@moeveglobal.com con su Excel y fotografías. No descarga archivos en el iPhone.</div><div class="mini-note">Asunto: ${esc(current?.name||'ESTACIÓN')} - ${esc(getConcession(current?.id)||'Nº CONCESIÓN')} - ${visitDateForStation(current?.id)} - VISITA</div><button class="primary-btn" onclick="sendCurrentVisitEmail()">Enviar visita</button></div><div class="card"><b>Persistencia</b><div class="muted">Las respuestas se guardan automáticamente. No hace falta exportar entre estaciones.</div></div>`);
  }else{
    showModal(`<div class="eyebrow">SALIDA / BACKUP</div><h2>Visitas de campo</h2><div class="card tint-blue"><h3>Enviar estación actual</h3><button class="primary-btn" onclick="sendCurrentVisitEmail()">Enviar visita por email</button></div><div class="card"><h3>Excel maestro</h3><div class="muted">Salida de auditoría con todas las estaciones y visitas guardadas.</div><button class="secondary-btn" onclick="exportExcel()">Descargar Excel maestro</button></div><div class="card"><h3>Backup completo</h3><button class="secondary-btn" onclick="exportVisitPackage()">Descargar Excel + fotos</button></div>`);
  }
};

function persist(updateStatus=true){state.__lastSavedAt=new Date().toISOString();localStorage.setItem('moeve_v32_state',JSON.stringify(state));if(updateStatus)updateSaveStatus();}
function showModal(html){document.getElementById('modalContent').innerHTML=html;document.getElementById('modalBackdrop').classList.remove('hidden');}
function closeModal(){document.getElementById('modalBackdrop').classList.add('hidden');}window.closeModal=closeModal;
function activateTab(name){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.view===name));document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===name));}window.activateTab=activateTab;
function bindUI(){
  document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>activateTab(b.dataset.view));
  document.querySelectorAll('.scope-btn').forEach(b=>b.onclick=()=>setPilotScope(b.dataset.scope));updateScopeUI();
  document.querySelectorAll('.map-filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.scope-btn').forEach(b=>b.onclick=()=>setPilotScope(b.dataset.scope));updateScopeUI();
  document.querySelectorAll('.map-filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');currentFilter=b.dataset.filter;renderMarkers();});
  document.getElementById('refreshData').onclick=loadStations;document.getElementById('exportBtn').onclick=openExportMenu;document.getElementById('closeModal').onclick=closeModal;document.getElementById('modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal();};document.getElementById('prevStop').onclick=()=>goRoute(-1);document.getElementById('nextStop').onclick=()=>goRoute(1);
}
function initMap(){map=L.map('map',{zoomControl:true,preferCanvas:true,tap:true}).setView([39.30,-1.95],7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);markerLayer=L.layerGroup().addTo(map);pilotRouteLayer=L.layerGroup().addTo(map);routeLayer=L.layerGroup().addTo(map);}
window.addEventListener('DOMContentLoaded',()=>{initMap();bindUI();updateSaveStatus();loadStations();});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')persist(false);});window.addEventListener('pagehide',()=>persist(false));
